\par \pard\fi0\li0\qj\ri255\sb0\sa0\itap0 
\par \pard\fi0\li0\qj\ri255\sb0\sa0\itap0 Lage 1: 
\par \pard\fi0\li0\qj\ri255\sb0\sa0\itap0 Dreiberg (Berge/Himmelsk\u246 \'f6rper - Dreiberg - frei - Beizeichen einkonturige Stange - Kreuz senkrecht - einkonturig - ohne weiteres Beizeichen) mit Formenpaar, Typ zu WZIS DE5580-Clm6539_46 (15. Jh.) und zu PO 150233 (1406, Rom); das gleiche Wasserzeichen auch in {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 UB Leipzig, Ms 1130}}\plain \f1\lang1033\fs20  (Lage 1\endash 8, hinterer Spiegel), {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Ms 1186}}\plain \f1\lang1033\fs20  (Lage 8, nur fol. 73), {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Ms 1414}}\plain \f1\lang1033\fs20  (Lage 10\endash 13) und {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Ms 1429}}\plain \f1\lang1033\fs20  (Lage 1, 26) \endash  alle jeweils um 1418\endash 1422.
\par \pard\fi0\li0\qj\ri255\sb0\sa0\itap0 
\par \pard\fi0\li0\qj\ri255\sb0\sa0\itap0 \u220 \'dcbriger Buchblock: 
\par \pard\li720\fi-360\jclisttab\tx0\qj\ri255\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls2\ilvl0 Mohrenkopf 1 (Figuren, anthropomorphe - PO-Mensch - Kopf - Mohr mit Stirnband, ein Schlaufenende \endash  Ohne Bindedraht\u252 \'fcberschneidung - Kontur des Hinterkopfs unterbrochen), das eine Wasserzeichen Typ zu DE4620-PO-20069 (Breslau, 1418) und DE4620-PO-20068 (Breslau, 1418), das andere Wasserzeichen Variante zu DE4620-PO-20069 (Breslau, 1418) und zu WZMA, AT5000-993_34 (Vicenza, 1419/20).
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls2\ilvl0 \plain \f1\lang1033\fs20 Mohrenkopf 2 (Figuren, anthropomorphe - PO-Mensch - Kopf - Mohr mit Stirnband, ein Schlaufenende \endash  Ohne Bindedraht\u252 \'fcberschneidung - Kontur des Hinterkopfs unterbrochen), das eine Wasserzeichen Variante zu WZMA, AT5000-993_34 (Vicenza, 1419/20), das andere Wasserzeichen Variante zu WZMA AT5000-993_27 (Vicenza, 1419/20).
\plain\par \pard\fi0\li0\qj\ri255\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
