\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Item Amphorismi Ypocratis \plain \f1\lang1033\fs24 [2r-10v]\plain \f1\i\lang1033\fs24 . Item Prognosticorum \plain \f1\lang1033\fs24 [11r-15v]\plain \f1\i\lang1033\fs24 . Item de signis pestilencie ... \plain \f1\lang1033\fs24 [16r-v]\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Item tractatus de minucione\plain \f1\lang1033\fs24  [17r-18v]\plain \f1\i\lang1033\fs24 . Item lectura super Amphorismorum Ypocratis\plain \f1\lang1033\fs24  [20ra-98ra]\plain \f1\i\lang1033\fs24 . Item cautele circa urinas\plain \f1\lang1033\fs24  [98va-vb]\plain \f1\i\lang1033\fs24 . Item Amphorismi ... \plain \f1\lang1033\fs24 [Register: 150ra-152rb?]. \plain \f1\i\lang1033\fs24 Item tractatus de flebotomia et cauteriis \u8230 \'85\plain \f1\lang1033\fs24  [152va-154va]\plain \f1\i\lang1033\fs24 . Item Philaretus de pulsibus\plain \f1\lang1033\fs24  [154vb-156ra]. \plain \f1\i\lang1033\fs24 Item lectura super summam de pulsibus \u8230 \'85\plain \f1\lang1033\fs24  [157ra-173rb]. \plain \f1\i\lang1033\fs24 Item tractatus de simplicibus et proprietatibus \u8230 \'85\plain \f1\lang1033\fs24  [179ra-207vb?]. \plain \f1\i\lang1033\fs24 Item Anatomia Mundini \plain \f1\lang1033\fs24 [215ra-233rb]. \plain \f1\i\lang1033\fs24 Item liber Albumasaris Arabici de simplicibus medicinis ... \plain \f1\lang1033\fs24 [233va-250rb].\plain \f1\i\lang1033\fs24  Item de quibusdam medicinis cyrogitis \plain \f1\lang1033\fs24 [373v-375v]. \plain \f1\i\lang1033\fs24 Item Practica Rogerii \plain \f1\lang1033\fs24 [381r-425v].\plain \f1\i\lang1033\fs24  Item de causis composicionis medicinarum \plain \f1\lang1033\fs24 [426r-427r].\plain \f1\i\lang1033\fs24  Item ars graduandi medicinam compositam secundum opinionem Alchindi et Averonii \plain \f1\lang1033\fs24 [427v-428r]. 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Anschlie\u223 \'dfend, mit Kreuz markiert, von derselben Hand Erg\u228 \'e4nzung von wohl versehentlich vegessenen Inhalten: \plain \f1\i\lang1033\fs24 Item \lquote Michi competit\rquote  de regimine sanitatis\plain \f1\lang1033\fs24  [251r-373r]. \plain \f1\i\lang1033\fs24 Quidam in simplicibus \plain \f1\lang1033\fs24 [233va-250rb?]. \plain \f1\i\lang1033\fs24 Idem de uirtutibus et qualitatibus operacionis simplicium medicinarum \plain \f1\lang1033\fs24 [?].}

