\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >D<Eus, qui mirabiliter hominem creasti et mirabilius reformasti quique dedisti medicinam ad recuperandum sanitatem corporum humanorum}}\plain \f1\i\lang1033\fs24 , da benedictionem tuam super hec antidota, ut quorum introierint corpora sanitatem mentis et corporis percipere mereatur. Per Christum dominum nostrum.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Das einleitende Gebet als Benedictio super medicinam bzw. Consecratio herbarum in zahlreichen medizin Hss., z. B. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Rom, Biblioteca Apostolica Vaticana, Pal. lat. 1116}}\plain \f1\lang1033\fs24 , 113v, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pal. lat. 1229}}\plain \f1\lang1033\fs24 , 352v, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pal. lat. 1248}}\plain \f1\lang1033\fs24 , 44v, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pal. lat. 1268}}\plain \f1\lang1033\fs24 , 219v, {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pal. lat. 1338}}\plain \f1\lang1033\fs24 , 180v. Auch in {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mei\u223 \'dfen, StA, H 6}}\plain \f1\lang1033\fs24 , 46v, vgl. Beschreibung von Werner \plain \f1\scaps\lang1033\fs24 Hoffmann\plain \f1\lang1033\fs24 : https://resolver.staatsbibliothek-berlin.de/HSP0004E13400000000.}

